mods['model_router_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass, asdict\nfrom typing import Any\nimport os\n\n@dataclass(frozen=True)\nclass ModelProfile:\n    name: str; provider: str; strengths: tuple[str,...]; cost_per_million: float; latency_ms: int; context: int; enabled: bool=True\n\nDEFAULT_MODELS=(\n    ModelProfile('reasoning','openai',('reasoning','architecture','debugging','research'),10.0,1800,256000),\n    ModelProfile('coding','openai',('code','implementation','refactor','tests'),7.0,1200,256000),\n    ModelProfile('fast','openai',('chat','simple','routing','summarize'),2.0,500,128000),\n    ModelProfile('local','local',('private','offline','simple'),0.0,200,32768,False),\n)\nKEYWORDS={'reasoning':('architect','architecture','debug','root cause','trade-off','reason','design','حل','تصميم','تحليل'),'code':('code','implement','fix','refactor','test','build','backend','frontend','flutter','python','typescript','dart','برمج','كود','اصلح'),'research':('research','latest','docs','compare','source','بحث','توثيق','مصادر'),'simple':('hello','hi','summarize','translate','مرحبا','ترجم','لخص')}\n\ndef _score(p:ModelProfile,task:str,size:int,budget:float)->float:\n    text=task.lower(); score=0.0\n    for s in p.strengths:\n        score += 1.8*sum(k in text for k in KEYWORDS.get(s,()))\n    score += 1.5 if size<=p.context else -50\n    score += .5 if budget>=p.cost_per_million else -2\n    score += max(0,1-p.latency_ms/3000)\n    return score\n\ndef route(task:str,input_tokens:int=0,budget_usd:float=999.0,models=DEFAULT_MODELS)->dict[str,Any]:\n    ranked=sorted([m for m in models if m.enabled],key=lambda m:_score(m,task,input_tokens,budget_usd),reverse=True)\n    if not ranked or _score(ranked[0],task,input_tokens,budget_usd)<=-10: raise RuntimeError('No model can satisfy request/context/budget.')\n    return {'selected':asdict(ranked[0]),'candidates':[{'name':m.name,'score':round(_score(m,task,input_tokens,budget_usd),3)} for m in ranked],'strategy':'capability+context+budget+latency'}\n\ndef provider_ready(provider:str)->bool:\n    return bool({'openai':os.getenv('OPENAI_API_KEY',''),'anthropic':os.getenv('ANTHROPIC_API_KEY',''),'local':'1'}.get(provider,''))\n\ndef status()->dict[str,Any]: return {'version':'V9','router':'operational','providers':{p:provider_ready(p) for p in ('openai','anthropic','local')},'models':[asdict(m) for m in DEFAULT_MODELS]}\n"""
mods['browser_agent_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nfrom typing import Any\nfrom urllib.parse import urlparse\nimport re,time\nSAFE={'open','click','fill','press','scroll','wait','screenshot','extract'}; RISKY={'download','upload','submit','delete','purchase','login'}\n@dataclass\nclass BrowserStep: action:str; target:str=''; value:str=''; approved:bool=False\ndef validate_url(url:str,allowed_domains:set[str]|None=None)->bool:\n    p=urlparse(url)\n    return p.scheme in {'http','https'} and bool(p.hostname) and (not allowed_domains or p.hostname in allowed_domains or any(p.hostname.endswith('.'+d) for d in allowed_domains))\ndef plan(goal:str,urls:list[str]|None=None,allowed_domains:set[str]|None=None)->dict[str,Any]:\n    steps=[BrowserStep('open',u) for u in (urls or [])]\n    if re.search(r'fill|type|write',goal,re.I): steps.append(BrowserStep('fill',value=goal))\n    steps += [BrowserStep('screenshot'),BrowserStep('extract')]\n    checks=[]\n    for s in steps:\n        ok=s.action in SAFE or s.action in RISKY\n        if s.action=='open': ok=validate_url(s.target,allowed_domains)\n        risky=s.action in RISKY; checks.append({'ok':ok and (not risky or s.approved),'approval_required':risky,'step':asdict(s)})\n    return {'goal':goal,'steps':[asdict(s) for s in steps],'checks':checks,'ready':all(c['ok'] for c in checks),'driver':driver_status()}\ndef driver_status()->dict[str,Any]:\n    try: import playwright; return {'available':True,'driver':'playwright'}\n    except Exception: return {'available':False,'driver':'none','install_hint':'Install Playwright plus a browser for live execution.'}\nclass BrowserSession:\n    def __init__(self,allowed_domains:set[str]|None=None): self.allowed_domains=allowed_domains or set(); self.history=[]\n    def record(self,action:str,target:str=''): self.history.append({'ts':time.time(),'action':action,'target':target})\n    def snapshot(self): return {'steps':len(self.history),'history':list(self.history),'allowed_domains':sorted(self.allowed_domains)}\n"""
mods['mcp_ecosystem_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nfrom typing import Any\nimport json\nfrom urllib.request import Request,urlopen\n@dataclass\nclass MCPServer: name:str; transport:str; endpoint:str; enabled:bool=True; allowed_tools:tuple[str,...]=()\nclass MCPEcosystem:\n    def __init__(self): self.servers={}; self.tool_catalog={}\n    def register(self,s:MCPServer):\n        if s.transport not in {'stdio','http','streamable_http'}: raise ValueError('Unsupported MCP transport')\n        self.servers[s.name]=s\n    def disable(self,name:str): self.servers[name].enabled=False\n    def allow(self,server:str,tool:str)->bool:\n        s=self.servers.get(server); return bool(s and s.enabled and (not s.allowed_tools or tool in s.allowed_tools))\n    def register_tools(self,server:str,tools:list[dict[str,Any]]):\n        if server not in self.servers: raise KeyError(server)\n        s=self.servers[server]\n        for t in tools:\n            n=str(t.get('name',''))\n            if n and (not s.allowed_tools or n in s.allowed_tools): self.tool_catalog[f'{server}:{n}']=dict(t)\n    def catalog(self): return {'servers':[asdict(s) for s in self.servers.values()],'tools':self.tool_catalog}\n    def call_http(self,server:str,tool:str,args:dict[str,Any]):\n        s=self.servers.get(server)\n        if not s or s.transport not in {'http','streamable_http'}: raise ValueError('HTTP MCP server not configured')\n        if not self.allow(server,tool): raise PermissionError('MCP tool denied by policy')\n        body=json.dumps({'jsonrpc':'2.0','id':1,'method':'tools/call','params':{'name':tool,'arguments':args}}).encode(); req=Request(s.endpoint,data=body,headers={'Content-Type':'application/json'},method='POST')\n        with urlopen(req,timeout=30) as r: return json.loads(r.read().decode())\n"""
mods['deep_research_v3.py']="""from __future__ import annotations\nimport asyncio\nfrom dataclasses import dataclass,asdict\nfrom typing import Any,Callable,Awaitable\n@dataclass\nclass ResearchAgentResult: agent:str; query:str; findings:str; urls:list[str]\n@dataclass\nclass ResearchV3: question:str; agents:list[ResearchAgentResult]; synthesis:str; gaps:list[str]\nasync def multi_agent_research(question:str,searcher:Callable[[str],Awaitable[dict[str,Any]]]|None=None,questions:list[str]|None=None)->ResearchV3:\n    qs=questions or [f'official documentation and facts about {question}',f'independent evidence and pitfalls for {question}',f'current alternatives and trade-offs for {question}']\n    async def one(i,q):\n        if not searcher: return ResearchAgentResult(f'agent-{i+1}',q,'searcher_not_configured',[])\n        r=await searcher(q); return ResearchAgentResult(f'agent-{i+1}',q,str(r.get('text','')),list(r.get('urls',[])))\n    agents=list(await asyncio.gather(*(one(i,q) for i,q in enumerate(qs))))\n    synthesis='\\n\\n'.join(f'[{a.agent}] {a.query}\\n{a.findings[:8000]}' for a in agents)\n    gaps=['External source search is unavailable.'] if all(not a.urls for a in agents) else []\n    return ResearchV3(question,agents,synthesis,gaps)\n"""
mods['code_graph_v3.py']="""from __future__ import annotations\nimport re\nfrom collections import defaultdict\nfrom pathlib import PurePosixPath\nfrom typing import Iterable,Any\ndef build_graph(files:Iterable[Any])->dict[str,Any]:\n    files=list(files); paths={f.path for f in files}; nodes=[]; edges=[]\n    imports={}; symbols={}\n    for f in files:\n        symbols[f.path]=re.findall(r'^\\s*(?:class|def|async def|function|interface|type|enum)\\s+([A-Za-z_]\\w*)',f.content,re.M)[:300]\n        imports[f.path]=re.findall(r'^\\s*(?:from|import)\\s+([A-Za-z_][\\w./-]*)',f.content,re.M)[:300]; nodes.append({'id':f.path,'type':'file','symbols':symbols[f.path][:100]})\n    for src,imps in imports.items():\n        for imp in imps:\n            normalized=imp.replace('.','/').lstrip('./')\n            for target in paths:\n                stem=target.rsplit('.',1)[0]\n                if target==imp or stem.endswith(normalized) or PurePosixPath(target).stem==PurePosixPath(normalized).name:\n                    if target!=src: edges.append({'from':src,'to':target,'kind':'imports'})\n    reverse=defaultdict(list)\n    for e in edges: reverse[e['to']].append(e['from'])\n    return {'version':'3','nodes':nodes,'edges':edges,'reverse_dependencies':{k:sorted(set(v)) for k,v in reverse.items()},'stats':{'files':len(paths),'edges':len(edges),'symbols':sum(map(len,symbols.values()))}}\ndef impact(graph:dict[str,Any],changed:list[str])->dict[str,Any]:\n    reverse=graph.get('reverse_dependencies',{}); impacted=set(changed); q=list(changed)\n    while q:\n        x=q.pop()\n        for y in reverse.get(x,[]):\n            if y not in impacted: impacted.add(y); q.append(y)\n    return {'changed':sorted(set(changed)),'impacted':sorted(impacted-set(changed)),'blast_radius':len(impacted)}\n"""
mods['autonomous_loop_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nfrom typing import Any,Callable\n@dataclass\nclass LoopStep: name:str; status:str='pending'; output:Any=None\nclass AutonomousLoopV9:\n    def __init__(self,max_iterations:int=5): self.max_iterations=max(1,min(max_iterations,20)); self.steps=[]\n    def run(self,plan_fn:Callable[[],Any],execute_fn:Callable[[Any],Any],verify_fn:Callable[[Any],bool],repair_fn:Callable[[Any],Any]|None=None):\n        self.steps=[]; state=plan_fn(); self.steps.append(LoopStep('plan','done',state))\n        for i in range(self.max_iterations):\n            out=execute_fn(state); self.steps.append(LoopStep(f'execute_{i+1}','done',out))\n            if verify_fn(out): self.steps.append(LoopStep('verify','passed')); return {'status':'verified','iterations':i+1,'steps':[asdict(s) for s in self.steps]}\n            self.steps.append(LoopStep(f'verify_{i+1}','failed'))\n            if repair_fn is None: break\n            state=repair_fn(out); self.steps.append(LoopStep(f'repair_{i+1}','done',state))\n        return {'status':'needs_review','iterations':len([s for s in self.steps if s.name.startswith('execute_')]),'steps':[asdict(s) for s in self.steps]}\n"""
mods['swe_bench_v9.py']="""from __future__ import annotations\nimport subprocess,tempfile,shutil\nfrom pathlib import Path\nfrom dataclasses import dataclass\n@dataclass\nclass SWETask: id:str; repo:str; issue:str; base_commit:str=''\n@dataclass\nclass SWEResult: task_id:str; status:str; tests_ok:bool; output:str=''; mode:str='real_harness'\nclass SWEBenchHarness:\n    def __init__(self,timeout:int=180): self.timeout=timeout\n    def validate_task(self,t:dict):\n        req={'id','repo','issue'}; return {'ok':req.issubset(t),'missing':sorted(req-set(t))}\n    def run_command(self,cmd:list[str],cwd:str):\n        r=subprocess.run(cmd,cwd=cwd,capture_output=True,text=True,timeout=self.timeout); return {'ok':r.returncode==0,'stdout':r.stdout[-10000:],'stderr':r.stderr[-10000:],'returncode':r.returncode}\n    def prepare_repo(self,repo_url:str)->str:\n        if not repo_url.startswith('https://github.com/'): raise ValueError('Only GitHub HTTPS repos are allowed.')\n        td=tempfile.mkdtemp(prefix='nexcode-swe-'); dst=str(Path(td)/'repo'); r=subprocess.run(['git','clone','--depth','1',repo_url,dst],capture_output=True,text=True,timeout=self.timeout)\n        if r.returncode!=0: shutil.rmtree(td,ignore_errors=True); raise RuntimeError((r.stdout+r.stderr).strip()[-4000:])\n        return dst\ndef score(results:list[SWEResult]):\n    return {'tasks':len(results),'resolved':sum(x.tests_ok for x in results),'pass_rate':round(100*sum(x.tests_ok for x in results)/len(results),2) if results else 0,'mode':'real_harness'}\n"""
mods['enterprise_security_v9.py']="""from __future__ import annotations\nimport hashlib,hmac,re,time\nfrom dataclasses import dataclass,asdict\nSECRET_RE=re.compile(r'(sk-[A-Za-z0-9_-]{10,}|gh[pousr]_[A-Za-z0-9_]{10,}|Bearer\\s+[A-Za-z0-9._-]{12,})')\nROLES={'owner':{'read','write','review','deploy','admin'},'admin':{'read','write','review','deploy','admin'},'developer':{'read','write','review'},'reviewer':{'read','review'},'viewer':{'read'}}\n@dataclass\nclass AuditEvent: ts:float; actor:int; action:str; resource:str; outcome:str\nclass SecurityEngine:\n    def __init__(self,project_secret='nexcode-v9'): self.events=[]; self.members={}; self.project_secret=project_secret.encode()\n    def grant(self,user_id:int,project_id:int,role:str):\n        if role not in ROLES: raise ValueError('invalid role')\n        self.members[(user_id,project_id)]=role\n    def allowed(self,user_id:int,project_id:int,action:str)->bool: return action in ROLES[self.members.get((user_id,project_id),'viewer')]\n    def audit(self,actor:int,action:str,resource:str,outcome:str): self.events.append(asdict(AuditEvent(time.time(),actor,action,resource,outcome)))\n    def redact(self,text:str)->str: return SECRET_RE.sub('[REDACTED]',text)\n    def sign(self,payload:str)->str: return hmac.new(self.project_secret,payload.encode(),hashlib.sha256).hexdigest()\n    def verify(self,payload:str,signature:str)->bool: return hmac.compare_digest(self.sign(payload),signature)\n    def policy_report(self): return {'rbac':True,'audit_log':len(self.events),'secret_redaction':True,'signed_events':True,'roles':sorted(ROLES)}\n"""
mods['ide_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nimport difflib\n@dataclass\nclass EditorFile: path:str; content:str; cursor:int=0\nclass IDEV9:\n    def __init__(self): self.files={}; self.active=''\n    def open(self,path,content): self.files[path]=EditorFile(path,content); self.active=path; return asdict(self.files[path])\n    def edit(self,path,new_content):\n        old=self.files.get(path,EditorFile(path,'')).content; diff=''.join(difflib.unified_diff(old.splitlines(True),new_content.splitlines(True),fromfile=path,tofile=path)); self.files[path]=EditorFile(path,new_content); return {'path':path,'diff':diff,'lines':len(new_content.splitlines())}\n    def tree(self): return sorted(self.files)\n    def snapshot(self): return {'active':self.active,'files':[asdict(f) for f in self.files.values()]}\n"""
mods['artifacts_v9.py']="""from __future__ import annotations\nimport hashlib,re\nfrom dataclasses import dataclass,asdict\n@dataclass\nclass Artifact: id:str; kind:str; title:str; content:str; sha256:str\nclass ArtifactEngine:\n    def __init__(self): self.items={}\n    def create(self,title,kind,content):\n        aid=hashlib.sha256((title+kind+content).encode()).hexdigest()[:16]; a=Artifact(aid,kind,title,content,hashlib.sha256(content.encode()).hexdigest()); self.items[aid]=a; return a\n    def interactive_html(self,content): return '<!doctype html><html><body>'+re.sub(r'<script[^>]*>.*?</script>','',content,flags=re.I|re.S)+'</body></html>'\n    def list(self): return [asdict(a) for a in self.items.values()]\n"""
mods['collaboration_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass,asdict\nimport time\n@dataclass\nclass Presence: user_id:int; name:str; online:bool=True; last_seen:float=0\nclass RealtimeRoom:\n    def __init__(self,room_id): self.room_id=room_id; self.presence={}; self.events=[]\n    def join(self,user_id,name): self.presence[user_id]=Presence(user_id,name,True,time.time()); self.events.append({'type':'join','user_id':user_id,'ts':time.time()}); return self.snapshot()\n    def leave(self,user_id):\n        if user_id in self.presence: self.presence[user_id].online=False; self.events.append({'type':'leave','user_id':user_id,'ts':time.time()})\n    def op(self,user_id,operation): self.events.append({'type':'operation','user_id':user_id,'operation':operation,'ts':time.time()}); return len(self.events)\n    def snapshot(self): return {'room_id':self.room_id,'presence':[asdict(p) for p in self.presence.values()],'events':len(self.events)}\n"""
mods['dev_agents_v9.py']="""from __future__ import annotations\nimport re,json\nfrom dataclasses import dataclass,asdict\n@dataclass\nclass Finding: severity:str; category:str; message:str; path:str=''\nclass CodeReviewAgent:\n    def review(self,files):\n        out=[]\n        for f in files:\n            if 'except:' in f.content: out.append(Finding('high','reliability','Bare except hides failures',f.path))\n            if 'eval(' in f.content: out.append(Finding('critical','security','eval() detected',f.path))\n            if 'TODO' in f.content: out.append(Finding('low','maintainability','TODO remains',f.path))\n        return [asdict(x) for x in out]\nclass DependencyAgent:\n    def inspect(self,manifests):\n        out=[]\n        for path,content in manifests.items():\n            if path.endswith('requirements.txt'): names=re.findall(r'^([A-Za-z0-9_.-]+)',content,re.M)\n            elif path.endswith('pubspec.yaml'): names=re.findall(r'^  ([A-Za-z0-9_]+):',content,re.M)\n            elif path.endswith('package.json'):\n                try: names=list(json.loads(content).get('dependencies',{}))\n                except Exception: names=[]\n            else: names=[]\n            out.append({'path':path,'dependencies':names,'count':len(names)})\n        return out\nclass SecurityAuditorAgent:\n    def audit(self,files):\n        findings=CodeReviewAgent().review(files)\n        for f in files:\n            if re.search(r'password\\s*=\\s*[\\\'\"]',f.content,re.I): findings.append(asdict(Finding('critical','secrets','Possible hard-coded password',f.path)))\n            if 'http://' in f.content: findings.append(asdict(Finding('medium','transport','Insecure HTTP reference',f.path)))\n        return findings\nclass DeployAgent:\n    def plan(self,target,project_id):\n        if target not in {'docker','github-pages','render','vercel','railway'}: raise ValueError('Unsupported deploy target')\n        return {'target':target,'project_id':project_id,'approval_required':True,'steps':['prepare','build','healthcheck','publish']}\nclass MobileAgent:\n    def quick_actions(self): return ['new task','inspect project','run tests','review code','view logs','deploy']\n"""
mods['memory_learning_v9.py']="""from __future__ import annotations\nfrom dataclasses import dataclass\nimport time\n@dataclass\nclass MemoryEvent: key:str; value:str; feedback:str=''; confidence:float=.5; ts:float=0\nclass MemoryLearningLoop:\n    def __init__(self): self.events=[]\n    def observe(self,key,value,feedback='',confidence=.5): self.events.append(MemoryEvent(key,value,feedback,max(0,min(confidence,1)),time.time()))\n    def learn(self):\n        grouped={}\n        for e in self.events:\n            bonus=.2 if e.feedback.lower() in {'positive','accepted','correct'} else (-.2 if e.feedback.lower() in {'negative','rejected','wrong'} else 0)\n            grouped[e.key]={'value':e.value,'confidence':max(0,min(1,e.confidence+bonus)),'evidence':grouped.get(e.key,{}).get('evidence',0)+1}\n        return grouped\n    def recall(self,key): return self.learn().get(key)\n"""
mods['voice_agent_v9.py']="""class VoiceAgentV9:\n    def status(self):\n        try: import speech_recognition; stt=True\n        except Exception: stt=False\n        return {'stt_available':stt,'tts_provider':'adapter','streaming':False,'provider_neutral':True}\n    def intent(self,transcript):\n        t=transcript.lower().strip()\n        if not t: return {'intent':'empty'}\n        if any(x in t for x in ('deploy','publish','نشر')): return {'intent':'deploy','text':transcript}\n        if any(x in t for x in ('test','اختبر')): return {'intent':'test','text':transcript}\n        return {'intent':'developer_command','text':transcript}\n"""
